public CameraMove_1(playerid, step)//Câmeras da Grove Street
{
    switch (step)
    {
        case 0://Ponte da Grove
        {
            InterpolateCameraPos(playerid, 2326.4942, -1659.2431, 33.158, 2436.2652, -1658.6864, 16.229, 10000, CAMERA_MOVE);
            InterpolateCameraLookAt(playerid, 2406.8103, -1657.8389, 13.8706, 2525.2525, -1662.7397, 16.7505, 10000, CAMERA_MOVE);
            SetTimerEx("CameraMove_1", 10000, false, "ii", playerid, 1);
        }
        case 1://Visão da Grove
        {
            InterpolateCameraPos(playerid, 2436.2652, -1658.6864, 16.229, 2458.2019, -1658.7474, 24.3372, 5000, CAMERA_MOVE);
            InterpolateCameraLookAt(playerid, 2525.2525, -1662.7397, 16.7505, 2505.5, -1674.8963, 21.478, 5000, CAMERA_MOVE);
            SetTimerEx("CameraMove_1", 5000, false, "ii", playerid, 2);
        }
        default:
        {
            SetCameraBehindPlayer(playerid);
        }
    }
    return 1;
}
